/// Returns nullptr if msgid is not in the dialect.
inline const MsgInfo* find_msg_info(std::uint32_t msgid) {
    const auto* first = std::begin(kMsgTable);
    const auto* last = std::end(kMsgTable);
    const auto* it = std::lower_bound(first, last, msgid,
        [](const MsgInfo& info, std::uint32_t id) { return info.msgid < id; });
    return (it != last && it->msgid == msgid) ? it : nullptr;
}

